def plain(html): return re.sub(r'\s+', ' ', re.sub('<[^>]+>', ' ', html)).strip()
def render():
    ROOT.mkdir(exist_ok=True)
    index=[]
    for n,pg in enumerate(PAGES):
        slug=pg['slug']; url=BASE+(slug+'/' if slug else '')
        nav=''.join('<a '+('aria-current="page" ' if x['slug']==slug else '')+'href="'+BASE+(x['slug']+'/' if x['slug'] else '')+'">'+e(x['title'] if not x['slug'] else {'roles':'Roles','contracting':'Contracting','inquiry':'Inquiry','conversations':'Conversations','intervention':'Intervention','learning':'Learning','situations':'Practice','related-practice':'Connections','september-session':'September session','resources':'Resources'}[x['slug']])+'</a>' for x in PAGES)
        toc='<nav class="toc" aria-label="On this page"><p>On this page</p>'+''.join('<a href="#'+sec['id']+'">'+e(sec['title'])+'</a>' for sec in pg['sections'])+'</nav>'
        body=''.join('<section class="chapter-section" id="'+sec['id']+'"><h2>'+e(sec['title'])+'</h2>'+sec['body']+'</section>' for sec in pg['sections'])
        for sec in pg['sections']: index.append(dict(title=sec['title'],chapter=pg['title'],url=url+'#'+sec['id'],text=plain(sec['body'])))
        nextpg=PAGES[(n+1)%len(PAGES)]
        html='''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'''+f'<title>{e(pg["title"])} | Systemic consulting | Benjamin P Taylor</title><meta name="description" content="{e(pg["deck"])}"><link rel="canonical" href="https://antlerboy.com{url}"><meta property="og:title" content="{e(pg["title"])}"><meta property="og:description" content="{e(pg["deck"])}"><meta property="og:image" content="https://antlerboy.com{BASE}practice-map.png"><link rel="stylesheet" href="{BASE}style.css"><script defer src="{BASE}guide.js"></script>'+'''</head><body><a class="skip" href="#main">Skip to content</a><header><div class="mast"><a href="/" class="brand">Benjamin P Taylor <span>antlerboy</span></a><a href="/library/">Public work library ↗</a></div>'''+f'<nav class="chapters" aria-label="Guide chapters">{nav}</nav></header><main id="main"><div class="hero"><p class="eyebrow">A field guide · 2022–2026</p><h1>{e(pg["title"])}</h1><p class="deck">{e(pg["deck"])}</p><p class="edition">Benjamin P Taylor · First edition, 1 October 2026</p></div><div class="reading-layout">{toc}<article>{body}<nav class="next" aria-label="Next chapter"><span>Continue</span><a href="{BASE}{nextpg["slug"]+("/" if nextpg["slug"] else "")}">{e(nextpg["title"])} →</a></nav></article></div></main><footer><p>Systemic consulting · Benjamin P Taylor</p><p><a href="{BASE}resources/#lineage">Sources and scope</a> · <a href="https://github.com/antlerboy/aboutme/issues/1">Suggest a correction</a> · <a href="mailto:benjamin.taylor@redquadrant.com">Get in touch</a></p><p>Purpose, relationship, action, and learning. Keep the work ownable.</p></footer></body></html>'
        dest=ROOT/slug/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(html)
    (ROOT/'search.json').write_text(json.dumps(index,ensure_ascii=False,indent=2))
    print(f'Built {len(PAGES)} pages, {len(index)} searchable sections, '+str(sum(len(plain(x['body']).split()) for pg in PAGES for x in pg['sections']))+' words.')
if __name__=='__main__': render()
